#include <iostream>
#include <stack>
using namespace std;

int main() {
    string s;
    cin >> s;
    stack<char> stk;
    bool ok = true;
    for (char c : s) {
        if (c == '(') stk.push(c);
        else if (c == ')') {
            if (stk.empty()) { ok = false; break; }
            stk.pop();
        }
    }
    if (!stk.empty()) ok = false;
    cout << (ok ? "Yes" : "No") << endl;
    return 0;
}

#include <iostream>
#include <queue>
using namespace std;

int main() {
    int n;
    cin >> n;
    queue<int> q;
    for (int i = 1; i <= n; i++) q.push(i);
    while (!q.empty()) {
        cout << q.front() << " ";
        q.pop();
    }
    return 0;
}

#include <iostream>
#include <deque>
using namespace std;

int main() {
    deque<int> dq;
    dq.push_back(1);
    dq.push_back(2);
    dq.push_front(0);
    while (!dq.empty()) {
        cout << dq.front() << " ";
        dq.pop_front();
    }
    return 0;
}

#include <iostream>
#include <stack>
using namespace std;

int main() {
    int n;
    cin >> n;
    int a[100000], ans[100000];
    for (int i = 0; i < n; i++) cin >> a[i];
    stack<int> stk;
    for (int i = n - 1; i >= 0; i--) {
        while (!stk.empty() && a[stk.top()] <= a[i]) stk.pop();
        ans[i] = stk.empty() ? 0 : stk.top() - i;
        stk.push(i);
    }
    for (int i = 0; i < n; i++) cout << ans[i] << " ";
    return 0;
}

#include <iostream>
#include <deque>
using namespace std;

int main() {
    int n, k;
    cin >> n >> k;
    int a[100000];
    for (int i = 0; i < n; i++) cin >> a[i];
    deque<int> dq;
    for (int i = 0; i < n; i++) {
        while (!dq.empty() && a[dq.back()] >= a[i]) dq.pop_back();
        dq.push_back(i);
        if (dq.front() <= i - k) dq.pop_front();
        if (i >= k - 1) cout << a[dq.front()] << " ";
    }
    return 0;
}
